def extract_api_endpoints(js_code):
    tree = parse(js_code)
    endpoints = []

    for node in tree.body:
        if hasattr(node, 'expression') and hasattr(node.expression, 'call'):
            call = node.expression.call
            if hasattr(call, 'callee') and hasattr(call.callee, 'object') and hasattr(call.callee, 'property'):
                if isinstance(call.callee.object, dict) and isinstance(call.callee.property, str):
                    if call.callee.property.value in API_METHODS:
                        if hasattr(call.arguments, 'arguments'):
                            for arg in call.arguments.arguments:
                                if hasattr(arg, 'value') and isinstance(arg.value, str):
