### 📄 代码实现

```python
import argparse
import requests
from concurrent.futures import ThreadPoolExecutor
import json
import time
import socket

def is_graphql_endpoint(url):
    try:
        headers = {"Content-Type": "application/json"}
        payload = {"query": "{ __schema { types { name } } }"}
        response = requests.post(url, json=payload, headers=headers, timeout=10)
        if response.status_code == 200:
            try:
                data = json.loads(response.text)
                if "__schema" in data and "types" in data["data"]["__schema"]:
                    return True
            except json.JSONDecodeError:
                pass
    except requests.exceptions.RequestException:
        pass
    return False

def introspect_schema(url, headers=None):
    payload = {
        "query": """
        {
          __schema {
            types {
              name
              kind
              possibleTypes {
                name
              }
              fields {
                name
                args {
                  name
                  type {
                    name
                  }
                }
              }
            }
          }
        }
        """
    }

    try:
        response = requests.post(url, json=payload, headers=headers, timeout=10)
        if response.status_code == 200:
            data = json.loads(response.text)
            return data.get("data", {}).get("__schema", {})
        else:
            return None
    except requests.exceptions.RequestException as e:
        print(f"Error connecting to {url}: {e}")
        return None

def scan_target(url, headers=None):
    print(f"Scanning {url}")
    if is_graphql_endpoint(url):
        print(f"[+] Found GraphQL endpoint at {url}")
        schema = introspect_schema(url, headers=headers)
        if schema:
            print("[+] Successfully retrieved schema:")
            print(json.dumps(schema, indent=2))
            return schema
    return None

def main():
    parser = argparse.ArgumentParser(description="GraphQL Introspection Scanner")
    parser.add_argument("-u", "--url", required=True, help="GraphQL endpoint URL")
    parser.add_argument("-t", "--threads", type=int, default=5, help="Number of threads")
    parser.add_argument("-H", "--headers", nargs='*', action='append', help="Custom headers (e.g., -H 'Authorization: Bearer token' -H 'Content-Type: application/json')")
    args = parser.parse_args()

    headers = {}
    if args.headers:
        for h in args.headers:
            if ":" in h:
                key, val = h.split(":", 1)
                headers[key.strip()] = val.strip()

    if not args.url:
        parser.print_help()
        return

    start_time = time.time()
    with ThreadPoolExecutor(max_workers=args.threads) as executor:
        results = list(executor.map(lambda x: scan_target(x, headers=headers), [args.url] * args.threads))

    print(f"[+] Scan completed in {time.time() - start_time:.2f} seconds")

if __name__ == "__main__":
    main()
```

