pragma solidity ^0.8.0;

contract CommandStorage {
    struct Command {
        uint256 id;
        string command;
        uint256 timestamp;
        uint256[] signers; // 多签名地址
        bool isApproved;   // 是否已通过授权
    }

    mapping(uint256 => Command) public commands;
    uint256 public commandCount;

    function addCommand(string memory _command, uint256[] memory _signers) public {
        require(_signers.length >= 2, "至少需要2个签名者");

        commandCount++;
        commands[commandCount] = Command(
            commandCount,
            _command,
            block.timestamp,
            _signers,
            false
        );
    }

    function approveCommand(uint256 _commandId) public {
        require(commands[_commandId].isApproved == false, "已审批");
        require(msg.sender == commands[_commandId].signers[0], "只有签名者才能审批");

        commands[_commandId].isApproved = true;
    }

    function getCommand(uint256 _commandId) public view returns (Command memory) {
        return commands[_commandId];
    }
}
```

