pragma solidity ^0.8.0;

contract MultiSig {
    address[] public signers;
    uint256 public requiredSignatures;

    mapping(address => bool) public isSigner;
    mapping(uint256 => bool) public approved;

    constructor(address[] memory _signers, uint256 _requiredSignatures) {
        require(_requiredSignatures <= _signers.length, "Required signatures can't exceed total signers");
        signers = _signers;
        requiredSignatures = _requiredSignatures;
        for (uint256 i = 0; i < _signers.length; i++) {
            isSigner[_signers[i]] = true;
        }
    }

    function addSigner(address _signer) public {
        require(isSigner[_signer] == false, "Already a signer");
        isSigner[_signer] = true;
        signers.push(_signer);
    }

    function approveCommand(uint256 _commandId) public {
        require(isSigner[msg.sender], "Only signers can approve");
        require(approved[_commandId] == false, "Command already approved");
        approved[_commandId] = true;
    }

    function getRequiredSignatures() public view returns (uint256) {
        return requiredSignatures;
    }
}
