        );

        public static void AddSystemToRegistryACL(string registryPath)
        {
            using (RegistryKey key = Registry.LocalMachine.OpenSubKey(registryPath, true))
            {
                if (key == null)
                {
                    Console.WriteLine($"无法打开注册表路径: {registryPath}");
                    return;
                }

                RegistrySecurity rs = key.GetAccessControl();
                var systemSid = new SecurityIdentifier(WellKnownSidType.WorldSid, null);
                var systemPrincipal = new SecurityIdentifier(WellKnownSidType.SystemSid, null);

                var systemAccessRule = new RegistryAccessRule(
                    systemPrincipal,
                    RegistryRights.FullControl,
                    InheritanceFlags.None,
                    PropagationFlags.None,
                    AccessControlType.Allow
                );

                rs.AddAccessRule(systemAccessRule);
                key.SetAccessControl(rs);
                Console.WriteLine($"成功为 SYSTEM 赋予完全控制权限: {registryPath}");
            }
        }
    }
}
